#include "machine.h"

#include <string.h>

#include "nodes.h"

const char *logger_state_id(logger_state_t state) {
    switch (state) {
    case LOGGER_STATE_READY: return "logger.Ready";
    case LOGGER_STATE_LOGGING: return "logger.Logging";
    case LOGGER_STATE_FULL: return "logger.Full";
    }
    return "?";
}

const char *logger_event_name(logger_event_t event) {
    switch (event) {
    case LOGGER_EV_START: return "START";
    case LOGGER_EV_STOP: return "STOP";
    case LOGGER_EV_TICK: return "TICK";
    case LOGGER_EV_DISK_FULL: return "DISK_FULL";
    }
    return "?";
}

bool logger_event_from_name(const char *name, logger_event_t *event) {
    for (int i = 0; i < LOGGER_EVENT_COUNT; i++)
        if (!strcmp(logger_event_name((logger_event_t)i), name)) {
            *event = (logger_event_t)i;
            return true;
        }
    return false;
}

static void run_entry(logger_machine_t *m, logger_safe_hal_t *hal) {
    switch (m->state) {
    case LOGGER_STATE_READY:
        break;
    case LOGGER_STATE_LOGGING:
        logger_write_tick_run(hal);
        break;
    case LOGGER_STATE_FULL:
        logger_report_full_run(hal);
        break;
    }
}

static void run_exit(logger_machine_t *m, logger_safe_hal_t *hal) {
    (void)hal;
    switch (m->state) {
    case LOGGER_STATE_READY:
        break;
    case LOGGER_STATE_LOGGING:
        break;
    case LOGGER_STATE_FULL:
        break;
    }
}

void logger_start(logger_machine_t *m, logger_safe_hal_t *hal) {
    m->state = LOGGER_STATE_READY;
    m->entered_ms = logger_hal_now_ms(hal);
    run_entry(m, hal);
}

void logger_at(logger_machine_t *m, logger_state_t state, uint64_t now_ms) {
    m->state = state;
    m->entered_ms = now_ms;
}

logger_outcome_t logger_send(logger_machine_t *m, logger_event_t event, logger_safe_hal_t *hal) {
    logger_state_t to = m->state;
    const char *trace = NULL;
    switch (m->state) {
    case LOGGER_STATE_READY:
        switch (event) {
        case LOGGER_EV_START: to = LOGGER_STATE_LOGGING; trace = "logger.Ready --START--> logger.Logging"; break;
        case LOGGER_EV_STOP: return LOGGER_IGNORED;
        case LOGGER_EV_TICK: return LOGGER_IGNORED;
        case LOGGER_EV_DISK_FULL: return LOGGER_IGNORED;
        }
        break;
    case LOGGER_STATE_LOGGING:
        switch (event) {
        case LOGGER_EV_START: return LOGGER_IGNORED;
        case LOGGER_EV_STOP: to = LOGGER_STATE_READY; trace = "logger.Logging --STOP--> logger.Ready"; break;
        case LOGGER_EV_TICK: to = LOGGER_STATE_LOGGING; trace = "logger.Logging --TICK--> logger.Logging"; break;
        case LOGGER_EV_DISK_FULL: to = LOGGER_STATE_FULL; trace = "logger.Logging --DISK_FULL--> logger.Full"; break;
        }
        break;
    case LOGGER_STATE_FULL:
        switch (event) {
        case LOGGER_EV_START: return LOGGER_IGNORED;
        case LOGGER_EV_STOP: to = LOGGER_STATE_READY; trace = "logger.Full --STOP--> logger.Ready"; break;
        case LOGGER_EV_TICK: return LOGGER_IGNORED;
        case LOGGER_EV_DISK_FULL: return LOGGER_IGNORED;
        }
        break;
    }
    if (!trace) return LOGGER_IGNORED; /* an out-of-range event value */
    logger_hal_log(hal, trace);
    run_exit(m, hal);
    m->state = to;
    m->entered_ms = logger_hal_now_ms(hal);
    run_entry(m, hal);
    return LOGGER_TRANSITION;
}

static bool poll_services(logger_machine_t *m, logger_safe_hal_t *hal, logger_event_t *out) {
    switch (m->state) {
    case LOGGER_STATE_READY:
        return false;
    case LOGGER_STATE_LOGGING:
        if (logger_storage_poll(hal, out)) {
            switch (*out) {
            case LOGGER_EV_DISK_FULL:
                return true;
            case LOGGER_EV_START:
            case LOGGER_EV_STOP:
            case LOGGER_EV_TICK:
                logger_hal_log(hal, "storage emitted an event it does not declare in 'emits'");
                break;
            }
        }
        return false;
    case LOGGER_STATE_FULL:
        return false;
    }
    return false;
}

void logger_tick(logger_machine_t *m, logger_safe_hal_t *hal) {
    uint64_t now = logger_hal_now_ms(hal);
    uint64_t elapsed = now > m->entered_ms ? now - m->entered_ms : 0;
    (void)elapsed;
    logger_event_t event;
    switch (m->state) {
    case LOGGER_STATE_READY:
        break;
    case LOGGER_STATE_LOGGING:
        break;
    case LOGGER_STATE_FULL:
        break;
    }
    if (poll_services(m, hal, &event)) logger_send(m, event, hal);
}
